import React from 'react';
import { motion } from 'framer-motion';

const Hero = () => {
  return (
    <section className="relative min-h-screen flex items-center justify-center bg-gradient-to-br from-blue-400 via-purple-500 to-purple-600 text-white overflow-hidden">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex items-center justify-between relative z-10">
        <motion.div
          className="flex-1 max-w-2xl"
          initial={{ opacity: 0, y: 50 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.8 }}
        >
          <h1 className="text-5xl lg:text-6xl font-bold mb-6 leading-tight">
            Smart Healthcare for Smart Students
          </h1>
          <p className="text-xl mb-8 opacity-90 leading-relaxed">
            Experience seamless health management with MediCampus. Book appointments,
            track queues, access digital records, and manage certificates all in one place.
          </p>
          <div className="flex gap-4 flex-wrap">
            <motion.button
              className="bg-green-400 hover:bg-green-500 text-white px-8 py-4 rounded-full text-lg font-semibold transition-all duration-300 hover:-translate-y-1 hover:shadow-xl hover:shadow-green-400/30"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              Book Appointment
            </motion.button>
            <motion.button
              className="bg-white/10 hover:bg-white/20 text-white px-8 py-4 rounded-full text-lg font-semibold border-2 border-white/30 hover:border-white/50 backdrop-blur-sm transition-all duration-300 hover:-translate-y-1"
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
            >
              View Queue
            </motion.button>
          </div>
        </motion.div>
        <motion.div
          className="flex-1 flex justify-center items-center"
          initial={{ opacity: 0, x: 50 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.8, delay: 0.2 }}
        >
          {/* Placeholder for illustration */}
          <div className="w-96 h-96 relative">
            <div className="w-full h-full rounded-full bg-white/10 absolute animate-pulse"></div>
            <div className="w-full h-full rounded-full bg-white/10 absolute animate-pulse" style={{ animationDelay: '1s' }}></div>
          </div>
        </motion.div>
      </div>
      <div className="absolute bottom-0 left-0 w-full h-24 bg-gradient-to-t from-white/25 via-white/50 to-white/75"></div>
    </section>
  );
};

export default Hero;
